"""Balance the questions generated by generate.py (the raw file is kept as is).

1. per video, at most --per-family questions of one family (yes / no families: alternating yes and no first);
2. group-1 yes / no answered "no" only at the end of the video: at most --max-no-at-end of the group-1 yes / no ones;
3. the position of the correct choice of group-1 questions cycles over all positions (the choices are rotated).
Everything is deterministic.

    python -m dataset_builders.clevrer_proactive.balance validation.json [--per-family 2] [--max-no-at-end 0.3]
"""
import argparse
import json
from collections import Counter, defaultdict

from .generate import OUT, rng_for


def stats(qs, title):
    fam = Counter(q["family"] for q in qs)
    n_vid = len({q["scene_index"] for q in qs})
    yn = [q for q in qs if q["group"] == 1 and q["answer_type"] == "yesno"]
    no_end = sum(bool(q.get("resolved_at_end")) for q in yn)
    pos = Counter(q["choices"].index(q["answers"][0]["answer"]) for q in qs if q["group"] == 1 and len(q["choices"]) == 4)
    print(f"\n== {title}: {len(qs)} questions, {len(qs) / n_vid:.1f} per video; group 1 / 2: "
          f"{sum(q['group'] == 1 for q in qs)} / {sum(q['group'] == 2 for q in qs)}")
    print("   families:", ", ".join(f"{f} {c / len(qs):.1%}" for f, c in fam.most_common()))
    print(f"   group-1 yes/no: {len(yn)}, yes {sum(q['answers'][0]['answer'] == 'yes' for q in yn)}, "
          f"no@end {no_end} ({no_end / max(1, len(yn)):.0%}), no earlier {sum(q['answers'][0]['answer'] == 'no' and not q.get('resolved_at_end') for q in yn)}")
    print("   correct position (4 choices):", dict(sorted(pos.items())))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("file")
    ap.add_argument("--per-family", type=int, default=2)
    ap.add_argument("--max-no-at-end", type=float, default=0.3)
    args = ap.parse_args()

    qs = json.loads((OUT / args.file).read_text(encoding="utf-8"))
    stats(qs, "raw")

    # 1. per-video family cap
    groups = defaultdict(list)
    for q in qs:
        groups[(q["scene_index"], q["family"])].append(q)
    kept = []
    for (sid, fam), g in groups.items():
        rng = rng_for(f"cap|{sid}|{fam}")
        g = g[:]
        rng.shuffle(g)
        if g[0]["answer_type"] == "yesno" and g[0]["group"] == 1:
            yes = [q for q in g if q["answers"][0]["answer"] == "yes"]
            no = [q for q in g if q["answers"][0]["answer"] == "no"]
            g = [q for pair in zip(yes, no) for q in pair] + yes[len(no):] + no[len(yes):]  # alternate yes / no
        kept += g[:args.per_family]

    # 2. cap "no, known only at the end"
    yn = [q for q in kept if q["group"] == 1 and q["answer_type"] == "yesno"]
    no_end = [q for q in yn if q.get("resolved_at_end")]
    others = len(yn) - len(no_end)
    limit = int(args.max_no_at_end * others / (1 - args.max_no_at_end))
    if len(no_end) > limit:
        no_end.sort(key=lambda q: rng_for("noend|" + q["id"]).random())
        drop = {q["id"] for q in no_end[limit:]}
        kept = [q for q in kept if q["id"] not in drop]

    # 3. rotate the choices so that the correct one cycles over the positions (per number of choices)
    kept.sort(key=lambda q: (q["scene_index"], q["id"]))
    counter = Counter()
    for q in kept:
        if q["group"] != 1 or q["answer_type"] == "yesno":
            continue
        n = len(q["choices"])
        target = counter[n] % n
        counter[n] += 1
        ch = q["choices"][:]
        ans = q["answers"][0]["answer"]
        ch.remove(ans)
        q["choices"] = ch[:target] + [ans] + ch[target:]

    stats(kept, "balanced")
    name = args.file.replace(".json", "_balanced.json")
    (OUT / name).write_text(json.dumps(kept, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"\n-> {OUT / name}")


if __name__ == "__main__":
    main()
